from collections import deque
R,C=len(grid),len(grid[0]); seen=set(); centers=[]
for r in range(R):
 for c in range(C):
  if grid[r][c] and (r,c) not in seen:
   q=deque([(r,c)]); seen.add((r,c)); comp=[]
   while q:
    x,y=q.popleft(); comp.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     a,b=x+dx,y+dy
     if 0<=a<R and 0<=b<C and grid[a][b]!=0 and (a,b) not in seen:
      seen.add((a,b));q.append((a,b))
   if any(grid[x][y]==3 for x,y in comp): centers += [(x,y) for x,y in comp if grid[x][y]==2]
print('centers',centers)
out=[row[:] for row in grid]
for r,c in centers:
 for x in range(max(0,r-1),min(R,r+2)):
  for y in range(max(0,c-1),min(C,c+2)):
   if (x,y) != (r,c): out[x][y]=1
print('\n'.join(' '.join(map(str,row)) for row in out))

target_centers=[p for p in centers if p not in [(4,12),(10,18),(10,19),(11,18)]]
out2=[row[:] for row in grid]
for r,c in target_centers:
 for x in range(max(0,r-1),min(R,r+2)):
  for y in range(max(0,c-1),min(C,c+2)):
   if (x,y)!=(r,c): out2[x][y]=1
for r,c in target_centers: out2[r][c]=2
print(target_centers)
print('\n'.join(' '.join(map(str,row)) for row in out2))
